from fractions import Fraction
from itertools import product
from typing import Sequence, Tuple

def occurrence_count(pattern: Sequence[int], volume: Sequence[int]) -> int:
    L, k = len(volume), len(pattern)
    if k > L:
        return 0
    return sum(1 for i in range(L - k + 1)
               if all(volume[i + j] == pattern[j] for j in range(k)))

def expected_bruteforce(pattern: Sequence[int], b: int, L: int) -> Fraction:
    total = sum(occurrence_count(pattern, v) for v in product(range(b), repeat=L))
    return Fraction(total, b ** L)

def expected_formula(b: int, L: int, k: int) -> Fraction:
    return Fraction(L - k + 1) * Fraction(1, b ** k)

# Exercise the main theorem: brute force over all 1024 binary volumes
b, L, pattern = 2, 10, (0, 1)
brute = expected_bruteforce(pattern, b, L)
form = expected_formula(b, L, len(pattern))
print("brute =", brute, " formula =", form, " match =", brute == form)
assert brute == form  # E[occurrences] = (L-k+1)*b^(-k) = 9/4

